#pragma once

#include <vector>
#include <thread>

#include "GL/glew.h"
#include <glm/glm.hpp>

#include "Particle.h"
#include "Geometry.h"

/// Settings which can alter the SPH simulation
struct SPHSettings
{
    SPHSettings(
        float mass, float restDensity, float gasConst, float viscosity,
        float h, float g, float tension);

    glm::mat4 sphereScale;
    float poly6, spikyGrad, spikyLap, gasConstant, mass, h2, selfDens,
        restDensity, viscosity, h, g, tension, massPoly6Product;
};

class SPHSystem
{
private:
    SPHSettings settings;
    size_t particleCubeWidth;

	bool started;
    bool runOnGPU;

	//initializes the particles that will be used
	void initParticles();

	// Sphere geometry for rendering
	Geometry* sphere;
	glm::mat4* sphereModelMtxs;
	GLuint vbo;

public:
	SPHSystem(
        size_t numParticles, const SPHSettings &settings,
        const bool &runOnGPU);
	~SPHSystem();

	Particle *particles;
    size_t particleCount;

	//updates the SPH system
	void update(float deltaTime);

	//draws the SPH system & its particles
	void draw(const glm::mat4& viewProjMtx, GLuint shader);

	void reset();
	void startSimulation();
};

/// Methods for interacting with the particle neighbor hash table

#ifndef SPH_NEIGHBORTABLE_H
#define SPH_NEIGHBORTABLE_H

#include <Particle.h>
#include <SPHSystem.h>

const uint32_t TABLE_SIZE = 262144;
const uint32_t NO_PARTICLE = 0xFFFFFFFF;

/// Returns a hash of the cell position
uint32_t getHash(const glm::ivec3 &cell);

/// Get the cell that the particle is in.
glm::ivec3 getCell(Particle *p, float h);

/// Creates the particle neighbor hash table.
/// It is the caller's responsibility to free the table.
uint32_t* createNeighborTable(
    Particle *sortedParticles, const size_t &particleCount);

#endif //SPH_NEIGHBORTABLE_H

